    static let trafficStopBribeV1 = SmallCases.make(
        key: "story.trafficStopBribe",
        category: .whiteCollar,
        headlines: ["Folded Bills Found Inside Registration Packet at Night Checkpoint", "Dash Camera Catches Driver Offering Cash to Deputy"],
        law: "bribery",
        threshold: 6,
        spec: "Offered a thing of value to a public official, a deputy, to influence an official act, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "At a night checkpoint on {DATE}, a deputy cited {D} for an expired tag. When {D} handed back the registration packet, three folded $100 bills were tucked inside and {D} said, \"Keep the change, we're good here.\" The deputy's dash camera recorded the handoff. {DL} says {D.he} thought tag fines could be paid on the spot.",
        state: [E(.video, 3, "Dash Camera", "{D} passes a packet through the window and says, 'Keep the change, we're good here.'"), E(.physical, 3, "Folded Bills", "Three $100 bills tucked inside the registration packet.", .search)],
        defense: [E(.statement, 1, "Paying the Fine", "{DL} says {D.he} thought the deputy could take payment for the tag fine.")],
        role: "Sheriff's deputy",
        exam: [.direct("What do you do as a sheriff's deputy?", "\"I patrol the county and work traffic checkpoints at night. I check licenses, tags, and insurance, and I issue citations.\""), .direct("What happened at the checkpoint on {DATE}?", "\"I cited {D} for an expired tag. I explained the citation and handed the paperwork back.\""), .direct("What did {D} do?", "\"When {D} handed back the registration packet, three folded $100 bills were tucked inside.\""), .direct("What did {D} say?", "\"Keep the change, we're good here. My dash camera recorded the handoff.\""), .direct("What did you do?", "\"I declined the money. I told {D} that I do not accept payment for citations, and I called a supervisor.\""), .direct("What did you learn about {D}'s phone?", "\"{D} searched that week for what an officer would take to skip a tag citation. I noted it.\""), .cross("Did {D} say anything about paying the fine?", "\"Yes. {D} said {D} thought tag fines could be paid on the spot. {D} said so right after.\""), .cross("Was there a clerk's fee schedule in the glove box?", "\"Yes. It listed an on-site payment line for tags. That could explain the confusion.\""), .cross("Did {D} try to hide the money?", "\"The bills were tucked into the packet. I do not know whether that was to hide them or just to hand them over.\""), .cross("Was {D} cooperative afterward?", "\"Yes. {D} took the money back and apologized. {D} said it was a misunderstanding.\""), .cross("Did {D} threaten you?", "\"No. {D} was polite. I did not feel threatened.\"")],
        theory: ("{D} slipped cash to a deputy to make a citation go away.", "A driver who misunderstood how a tag fine is paid."),
        allocution: "\"I made a bad choice at that window. I'm sorry.\"",
        truths: ("{DL}'s phone shows a search that week for what an officer would take to skip a tag citation.", "{DL} had a clerk's fee schedule in the glove box that listed an on-site payment line for tags."),
        defendant: [.direct("Tell us about the checkpoint.", "\"I was stopped at a night checkpoint. The deputy cited me for an expired tag, and I wanted to resolve it.\""), .direct("Why did you put money in the packet?", "\"I thought tag fines could be paid on the spot. I had a clerk's fee schedule in my glove box that listed an on-site payment line for tags.\""), .direct("What did you mean by keep the change?", "\"I meant to pay the fee and let the deputy keep the extra. I did not mean a bribe.\""), .direct("Why did you search about officers and tags?", "\"I wanted to know how fines work. I did not know the right way, and I should have asked.\""), .direct("What did you do when the deputy declined?", "\"I took the money back and apologized. I said I did not mean anything wrong.\""), .direct("How has this affected you?", "\"Embarrassed, more than anything. I misunderstood. I did not mean to offer a bribe, and I wish I had asked first.\""), .cross("You put $300 in a registration packet, didn't you?", "\"Yes. I did. I thought it was a fee, and I know it was too much.\""), .cross("You said keep the change, didn't you?", "\"Yes. I did. I know how that sounds.\""), .cross("You searched what an officer would take to skip a tag citation, didn't you?", "\"Yes. I did. I know the wording looks bad.\""), .cross("The fee schedule was in your glove box, wasn't it?", "\"Yes. It listed an on-site payment line. I misunderstood it.\""), .cross("The deputy did not offer to take payment, did the deputy?", "\"No. The deputy said no right away. I should have listened.\"")],
        openings: ("At a night checkpoint on {DATE}, a deputy cited {D} for an expired tag. When {D} handed back the registration packet, three folded $100 bills were tucked inside and {D} said, Keep the change, we're good here, and the dash camera recorded it.", "The defense will present a clerk's fee schedule with an on-site payment line, and a driver who thought a tag fine could be paid on the spot. A misunderstanding about a fee is not a bribe."),
        closings: ("Three $100 bills in a registration packet, the words keep the change, we're good here, and a search that week for what an officer would take to skip a citation. The dash camera recorded it.", "A fee schedule that listed on-site payment and a driver who thought it was a fine. The State has not proved that {D} meant to bribe the deputy."),
        timeline: [(0, "10:40 p.m.: {DL} is stopped at the checkpoint."), (0, "10:48 p.m.: the packet is returned with cash inside."), (0, "11:05 p.m.: {DL} is arrested.")],
        identified: "The deputy's dash camera.",
        mood: .indifferent)

    static let busPhoneSnatchV1 = SmallCases.make(
        key: "story.busPhoneSnatch",
        category: .property,
        headlines: ["Phone Left on Cafe Patio Table Vanishes Under a Napkin", "Tracking App Leads Owner to Neighboring Table's Diner"],
        law: "misdLarceny",
        spec: "Stole a phone valued at $800 belonging to {V}, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "{V} left a phone on a patio table at a sidewalk cafe while stepping inside to order on {DATE}. A cafe camera showed {D}, at the next table, slide a napkin over it and drop it into a tote. A tracking app put the phone a few blocks away within the hour. {DL} says {D.he} meant to hand it to the cafe staff.",
        state: [E(.video, 3, "Cafe Camera", "{D} covers the phone with a napkin and places it in a tote."), E(.digital, 3, "Tracking App", "The phone's location moves from the cafe to {D}'s street.")],
        defense: [E(.statement, 1, "Meant to Turn In", "{DL} says {D.he} meant to give it to the staff.")],
        role: "Cafe patron",
        exam: [.direct("Describe your morning at the cafe for the jury.", "\"I was at a sidewalk cafe having coffee. I left my phone on a patio table while I stepped inside to order.\""), .direct("What did you find when you came back?", "\"My phone was gone. I looked around, and I asked staff. No one had seen it.\""), .direct("What did the cafe camera show?", "\"{D}, at the next table, sliding a napkin over my phone and dropping it into a tote.\""), .direct("How did you track the phone?", "\"A tracking app showed the phone moving from the cafe to {D}'s street within the hour.\""), .direct("What happened to the phone?", "\"It was switched off in the first block after leaving. I could not reach it by calling.\""), .direct("How did this affect you?", "\"I lost contacts, photos, and work messages. I was frightened and had to cancel cards.\""), .cross("Did you see {D} take the phone?", "\"Only on the camera. I was inside when it happened, and I cannot say what {D} intended.\""), .cross("Did {D} ask staff about lost-and-found?", "\"A barista says {D} asked where the lost-and-found box was. I did not hear that myself.\""), .cross("Did {D} return the phone?", "\"No. It was switched off and moved to {D}'s street. I recovered it later with help from deputies.\""), .cross("Could {D} have meant to hand it in?", "\"{D} says so. I cannot say. I know the napkin and the tote did not look like handing it in.\""), .cross("Was anything damaged?", "\"No. The phone was not damaged. I just lost time and felt violated.\"")],
        theory: ("{D} covered a phone and carried it away.", "A diner who meant to turn a phone in."),
        allocution: "\"I should have walked it to the counter. I'm sorry.\"",
        truths: ("{DL} switched the phone off in the first block after leaving.", "A barista says {DL} asked where the lost-and-found box was, and was told it was in the back."),
        defendant: [.direct("Tell the jury what happened.", "\"I was at the next table. I saw the phone and picked it up. I meant to give it to the cafe staff.\""), .direct("Why did you cover the phone with a napkin?", "\"To keep it from being seen. I did not want someone else to take it.\""), .direct("Why did you put it in a tote?", "\"So I would not lose it. I planned to hand it in at the counter.\""), .direct("Why did you switch the phone off?", "\"It was buzzing and I did not want it to ring. I was going to take it back.\""), .direct("Did you ask about the lost-and-found box?", "\"Yes. I asked a barista where it was, and was told it was in the back. I did not go there.\""), .direct("How has this affected you?", "\"The word for it is stupid. I should have walked straight to the counter. I did not mean to steal.\""), .cross("You covered the phone with a napkin, didn't you?", "\"Yes. I did. I know how that looks, and I should have taken it straight to the counter.\""), .cross("You dropped it in a tote, didn't you?", "\"Yes. I did. I meant to carry it safely, but I know it looks like hiding it.\""), .cross("You switched the phone off, didn't you?", "\"Yes. It was buzzing. I did not think about the tracking app.\""), .cross("The tracking app followed it to your street, didn't it?", "\"Yes. I walked home with it. I meant to bring it back, but I did not.\""), .cross("You never went to the lost-and-found box, did you?", "\"No. I was told it was in the back, and I did not go, and I regret that.\"")],
        openings: ("{V} left a phone on a patio table at a sidewalk cafe while stepping inside to order on {DATE}. A cafe camera showed {D}, at the next table, slide a napkin over it and drop it into a tote, and a tracking app put the phone a few blocks away within the hour.", "The defense will present a person who meant to hand the phone to the staff, who asked where the lost-and-found box was, and who made a poor choice. {D} did not mean to keep it."),
        closings: ("A napkin over the phone, a tote, a tracking app that follows the phone to {D}'s street, and a phone switched off in the first block. {V} lost the phone.", "A person who asked where the lost-and-found box was and meant to turn the phone in. The State has not proved that {D} meant to keep it."),
        timeline: [(0, "1:05 p.m.: {V} goes inside to order."), (0, "1:08 p.m.: {DL} covers the phone."), (0, "2:00 p.m.: the tracking app shows the phone on {DL}'s street.")],
        identified: "A cafe camera and a tracking app.",
        mood: .indifferent,
        genders: ["D": .male, "V": .female])

    static let funeralSceneV1 = SmallCases.make(
        key: "story.funeralScene",
        category: .publicOrder,
        headlines: ["Mourner Interrupts Graveside Service Over Money", "Pastor's Phone Video Shows Tent Shouting Match"],
        law: "disorderly",
        spec: "Engaged in disorderly conduct by making a public disturbance at a burial service, on {DATE}.",
        ages: 24...66,
        victim: false,
        summary: "During a graveside service at a church cemetery on {DATE}, {D} walked up to the tent, shouted at the family about a loan the deceased never repaid, and kicked over a standing flower arrangement. Mourners were still at the casket when a deputy arrived. {DL} says the deceased was a close friend and grief took over.",
        state: [E(.video, 3, "Pastor's Phone Video", "{D} shouts at the family and knocks over a flower stand during the committal."), E(.statement, 2, "Cemetery Caretaker", "{D} ignored two requests to step away from the tent.")],
        defense: [E(.statement, 1, "Close Friend", "{DL} says the deceased was a friend of thirty years.")],
        role: "Pastor",
        exam: [.direct("Describe your work as a pastor.", "\"I lead the congregation and conduct funerals. I try to bring comfort to families during the hardest days of their lives.\""), .direct("What happened during the graveside service on {DATE}?", "\"During the committal, {D} walked up to the tent and shouted at the family about a loan the deceased never repaid.\""), .direct("What did {D} do?", "\"{D} knocked over a standing flower arrangement. I recorded it on my phone, and the video shows the shouting and the flower stand.\""), .direct("How did the family react?", "\"They were shocked and in tears. Mourners were still at the casket, and some tried to calm {D}.\""), .direct("Did anyone ask {D} to leave?", "\"The cemetery caretaker asked {D} twice to step away from the tent. {D} ignored both requests.\""), .direct("What happened next?", "\"A deputy arrived while mourners were still at the casket. {D} left with the deputy.\""), .cross("Did {D} know the deceased?", "\"Yes. {D} says the deceased was a friend of thirty years. {D} was upset about the loan, and about the death.\""), .cross("Had {D} been drinking?", "\"I smelled alcohol. I learned later that {D} had been drinking from a bottle in the truck before the service.\""), .cross("Was {D} invited to speak?", "\"The family had promised to let {D} say a few words. I skipped the invitation, and that was my mistake.\""), .cross("Did {D} hit anyone?", "\"No. {D} did not touch anyone. {D} shouted and kicked over the flower stand.\""), .cross("Did {D} apologize?", "\"Yes. {D} apologized to me later and to the family. {D} said grief took over.\"")],
        theory: ("{D} turned a burial into a shouting match.", "A grieving friend who lost control for a few minutes."),
        allocution: "\"I wasn't myself. I'm ashamed of how it looked.\"",
        truths: ("{DL} had been drinking from a bottle in the truck before the service.", "The widow had promised to let {DL} say a few words and the pastor skipped the invitation."),
        defendant: [.direct("Describe the deceased in your own words.", "\"We were friends for thirty years. I loved my friend, and I was devastated by the death.\""), .direct("Why did you shout at the family?", "\"I was upset about a loan, and I was also drinking. Grief took over. I did not mean to disrupt the service.\""), .direct("Why did you knock over the flowers?", "\"I kicked the stand in anger. It was not aimed at anyone, and I know it was wrong.\""), .direct("Why did you ignore the caretaker?", "\"I was not thinking clearly. I did not hear the requests properly, and I was in a fog.\""), .direct("Had you been promised a chance to speak?", "\"The family had promised that I could say a few words. The pastor skipped the invitation, and I felt shut out.\""), .direct("How are you coping with what happened?", "\"The word for it is ashamed. I disrupted a funeral for a friend I loved. I am sorry to the family and to the pastor.\""), .cross("You shouted at the family, didn't you?", "\"Yes. I did. I was upset about the loan, and I know it was wrong.\""), .cross("You knocked over a flower stand, didn't you?", "\"Yes. I kicked it. It was not aimed at a person.\""), .cross("You had been drinking, hadn't you?", "\"Yes. I drank from a bottle in the truck before the service. I know that was a poor choice.\""), .cross("You ignored two requests to step away, didn't you?", "\"Yes. I did. I was not thinking clearly.\""), .cross("Mourners were still at the casket, weren't they?", "\"Yes. I know. I am ashamed of what I did at that service.\"")],
        openings: ("During a graveside service at a church cemetery on {DATE}, {D} walked up to the tent, shouted at the family about a loan the deceased never repaid, and kicked over a standing flower arrangement. Mourners were still at the casket when a deputy arrived.", "The defense will present a friend of thirty years whose grief took over, a promise to speak that was skipped, and a person who apologized. {D} did not mean to disrupt the service."),
        closings: ("Shouting at the family during the committal, a flower stand knocked over, two requests to step away that were ignored, and mourners still at the casket. The video shows it.", "A friend of thirty years whose grief took over, a promise to speak that was skipped, and an apology afterward. The State has not proved that {D} meant to disrupt the service."),
        timeline: [(-3, "The deceased dies after a short illness."), (0, "11 a.m.: the graveside service begins."), (0, "11:20 a.m.: {DL} shouts at the family."), (0, "11:35 a.m.: a deputy arrives.")],
        identified: "The pastor's phone video.",
        mood: .sympathetic,
        genders: ["D": .male])

    static let textMessagesV1 = SmallCases.make(
        key: "story.textMessages",
        category: .violent,
        headlines: ["Teen Charged After Voice Notes Pushed Partner Toward Suicide", "Cloud Account Reveals Months of Late-Night Recordings"],
        law: "invManslaughter",
        threshold: 3,
        spec: "By culpable negligence, through repeated recorded messages encouraging the suicide of {V}, unintentionally caused the death of {V.him}.",
        ages: 19...19,
        victim: true,
        summary: "{V} died by suicide at a lakeside dock on {DATE}. {V}'s sibling later opened a shared cloud account and found months of late-night voice notes from {D}, {V}'s partner, daring {V.him} to stop talking about it and do it. On the last night {D} sent a countdown recording and went to bed without telling anyone. The State says the voice notes were a cause of death. The defense says {V} had been in crisis for years and {D} was a teenager in crisis too.",
        state: [E(.digital, 4, "Voice Notes", "Dozens of late-night recordings from {D} pressing {V} to follow through, ending with a countdown the final night.", .search), E(.digital, 2, "Call Log", "A call between {D} and {V} ended eleven minutes before the time of death. {D} called no one afterward."), E(.statement, 2, "Message to a Friend", "Days later {D} wrote: 'I knew where {V.he} was going and I let it happen.'")],
        defense: [E(.document, 3, "Hospital Records", "{V} was admitted twice for depression before the relationship began."), E(.digital, 2, "Earlier Recordings", "For months before the change, {D} had sent hotline numbers and begged {V} to see a counselor.", .search)],
        role: "{V}'s sibling",
        exam: [.direct("What can you tell us about your relationship with {V}?", "\"{V} was my sibling. We were close, and we talked often, though {V} had been quieter in the months before.\""), .direct("How did you find the voice notes?", "\"After {V} died, I opened a shared cloud account we both used. It held months of late-night voice notes from {D}.\""), .direct("What did the voice notes say?", "\"At first, they were pleading and kind, asking {V} to see a counselor. Over time, they changed to pressure and anger.\""), .direct("What was the last night like?", "\"On the final night, {D} sent a countdown recording. {V} died at the lakeside dock eleven minutes after the last call.\""), .direct("Had {V} struggled before the relationship?", "\"Yes. {V} had been admitted twice to the hospital for depression, before {D} and {V} were together.\""), .direct("What did {V} say in the weeks before?", "\"{V} said things were fine. {V} was making plans for the summer, which is why this was such a shock.\""), .cross("Did {D} ever urge {V} to get help?", "\"In the early recordings, yes. {D} begged {V} to see a counselor.\""), .cross("Did {V} have a history of treatment before {D}?", "\"Yes. Two hospital stays and years of struggle.\""), .cross("Were the voice notes the only messages?", "\"There were also texts and calls. The voice notes were the ones I found.\""), .cross("Did {V} ever tell you about the messages?", "\"No. {V} never mentioned them.\""), .cross("Was {D} young at the time?", "\"Yes. {D} was a teenager, as {V} was.\"")],
        defenseRole: "School counselor",
        defenseExam: [.direct("What is your role, and how do you know {D}?", "\"I'm a school counselor. {D} came to see me twice in the months before.\""), .direct("What did {D} tell you?", "\"That {D} was scared for {V} and didn't know what to do. {D} was crying and said {V} talked about dying.\""), .direct("What did you advise?", "\"To tell {V}'s parents and to call a crisis line. I also called {D}'s parents.\""), .direct("How did {D} seem?", "\"Overwhelmed and frightened. {D} was a teenager who was out of depth.\""), .direct("Did {D} seem to want {V} to come to harm?", "\"No. {D} seemed desperate to help and unsure how.\""), .direct("Did you follow up?", "\"I met with {D} again a week later. {D} said things were getting worse.\""), .cross("Did you report your concerns about {V}?", "\"I advised {D} to tell the parents. I don't know if that happened.\""), .cross("Did you contact {V}'s family yourself?", "\"No. I contacted {D}'s family only, because {V} was not my student and I had no contact information.\""), .cross("Did {D} tell you about the voice notes?", "\"No. {D} never mentioned any voice notes or recordings to me in either of our meetings.\""), .cross("Did {D} say anything about 'doing it'?", "\"Not to me. I never heard {D} say anything like that in either of our meetings.\""), .cross("Would you have advised {D} differently if you'd known?", "\"Yes. I would have urged {D} to stop and to get help immediately.\"")],
        theory: ("{D} pushed a vulnerable partner for months and ignored a final warning.", "A teenager overwhelmed by a partner's long illness, not the cause of a death."),
        allocution: "\"I would give anything to take those recordings back.\"",
        truths: ("A friend later said {D} bragged that the grief would make people notice {D.him}.", "{V}'s journal, found later, showed the plan was fixed before the recordings turned."),
        defendant: [.direct("Describe your relationship with {V} for the jury.", "\"We were together for about a year. I cared about {V} and I was terrified of losing {V.him}.\""), .direct("Why did you send the recordings?", "\"I was exhausted and scared. {V} talked about dying every night, and I didn't know how to help.\""), .direct("Did you ever ask {V} to get help?", "\"Over and over, for a year. I begged {V} to see a counselor and I told {V}'s family.\""), .direct("What did you mean by the countdown?", "\"I thought it was a bluff. {V} had said it so many times that I started to think it was a way to hold on to me.\""), .direct("Why did you go to bed without telling anyone?", "\"I fell asleep. I wish I hadn't, every day.\""), .direct("How are you coping with what happened?", "\"I think about it all the time. I'm so sorry, and I'd do anything to go back.\""), .cross("You told {V} to 'do it.' Isn't that urging suicide?", "\"It was a stupid and terrible thing to say. I said it because I was desperate, not because I wanted {V} to die.\""), .cross("You called no one after the last call. Why?", "\"I thought {V} was fine. I didn't believe it.\""), .cross("You wrote to a friend that you let it happen. What did that mean?", "\"That I feel guilty. It wasn't a confession.\""), .cross("The voice notes got harsher over time. Why?", "\"I was running out of patience, and I wish I'd gotten help for myself.\""), .cross("A friend says you bragged that the grief would get you attention. Is that true?", "\"No. I never said that.\"")],
        openings: ("{V} died by suicide at a lakeside dock. {V}'s sibling later found months of late-night voice notes from {D}, daring {V.him} to stop talking about it and do it, and on the last night a countdown recording.", "{V} had been in crisis for years and in the hospital twice before {D}. Jurors will hear from a school counselor about a frightened teenager who begged for help and was overwhelmed."),
        closings: ("Months of voice notes that turned from pleading to pressure, a countdown on the last night, and no call for help. The recordings were a cause of death.", "Cruel words are not the legal cause of a death. {V} had struggled for years, and {D} was a teenager in crisis too, who asked for help and was not heard."),
        timeline: [(-200, "{D} begins urging {V} to see a counselor."), (-60, "The recordings turn from pleading to pressure."), (0, "11:10 p.m.: the last call ends."), (0, "11:21 p.m.: {V} dies at the dock."), (1, "{V}'s sibling finds the cloud account.")],
        identified: "Recordings in a shared cloud account.",
        aggravating: ["The victim was especially vulnerable"],
        mitigating: ["{DL} was a teenager and suffering from mental illness", "{DL} had previously urged {V} to seek treatment"],
        mood: .divided,
        impact: "I don't want revenge. I want every teenager who hears those recordings to know words can kill.")

    static let phantomLandlordV1 = SmallCases.make(
        key: "story.phantomLandlord",
        category: .whiteCollar,
        headlines: ["Family Pays for Lakeside Cabin That Was Never for Rent", "Stock Photos Behind Vacation Listing Traced to Another State"],
        law: "falsePretenses",
        spec: "Obtained $1,250 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} sent {D} $1,250 through a payment app for a week at a lakeside cabin advertised online. When {V} pulled up on {DATE}, a stranger at the cabin said it was never for rent. The listing's photos came from a real estate site in another state. {DL} says {D.he} managed the cabin for the owner's cousin and a double booking forced a cancellation.",
        state: [E(.digital, 3, "Rental Listing", "Photos copied from a real estate site and {D}'s phone number as contact."), E(.document, 3, "Payment App Record", "$1,250 sent to {D}'s account the same afternoon.")],
        defense: [E(.statement, 1, "Cousin's Cabin", "{DL} says {D.he} managed the cabin for the owner's cousin.")],
        role: "Renter",
        exam: [.direct("Tell the jury about your plans for the trip.", "\"I had planned a week at a lakeside cabin for my family. We had saved for it, and I found a listing online that looked perfect.\""), .direct("How did you pay?", "\"I sent $1,250 through a payment app to {D}'s account the same afternoon. The listing gave {D}'s phone number as the contact.\""), .direct("What happened when you arrived on {DATE}?", "\"A stranger at the cabin said it was never for rent. I was stunned, and my family was waiting in the car.\""), .direct("What did you learn about the listing's photos?", "\"They came from a real estate site in another state. The cabin in the pictures was not the one I had driven to.\""), .direct("What did you do next?", "\"I called {D} and got no real answer. I reported it to the sheriff and canceled the rest of the trip.\""), .direct("How did this affect you?", "\"We lost the money and the vacation. My children were disappointed, and I felt foolish and angry.\""), .cross("Did you speak with {D} before paying?", "\"Briefly, by phone and text. {D} seemed professional and friendly. I did not meet {D} in person.\""), .cross("Did {D} say the cabin was a double booking?", "\"Later, yes. {D} said a double booking forced a cancellation. I did not hear that before I drove there.\""), .cross("Did {D} offer a refund?", "\"Not that I received. I asked, and I did not get my money back.\""), .cross("Could the listing have been posted by someone else?", "\"I do not know. It carried {D}'s number, and the payment went to {D}'s account.\""), .cross("Did you check the listing before paying?", "\"I looked at the photos and the description. I did not search for the photos elsewhere, and I wish I had.\"")],
        theory: ("{D} rented out a cabin {D.he} had no right to.", "A manager whose booking fell through."),
        allocution: "\"I'll pay every cent back.\"",
        truths: ("{DL} posted the same cabin photos under three other lake towns.", "The owner's cousin texted {DL} a key code and a weekly price for that cabin before withdrawing the offer."),
