        defense: [E(.statement, 1, "Unknown Voice", "{DL} says a stranger in a hoodie shouted and never said 'deputy.'")],
        role: "Plainclothes deputy",
        exam: [.direct("What are your duties as a plainclothes deputy?", "\"I work in plain clothes on property complaints and shopping center problems. I wear a vest marked Sheriff, and I carry a badge on my belt.\""), .direct("Why were you at the shopping center on {DATE}?", "\"The center owner asked deputies to clear the loading dock of skaters. I went to respond to that complaint.\""), .direct("What happened when you called out?", "\"I called out to {D}, who was skating across the loading dock. I shouted deputy twice, according to a store clerk.\""), .direct("What did {D} do?", "\"{D} kicked off and ran. I followed, and caught {D} at a drainage path.\""), .direct("What happened when you caught {D}?", "\"I put a hand on {D}'s arm. {D} yanked the arm free. {D} gave a false first name.\""), .direct("What was your vest like?", "\"It was marked Sheriff and zipped under an open hoodie. The badge was not visible until we reached the drainage path.\""), .cross("Did you say who you were?", "\"I shouted deputy twice. A clerk says so. But the vest was under a hoodie, and {D} says {D} did not hear it.\""), .cross("Was the badge visible on the camera?", "\"No. The clip shows no badge until the drainage path. The hoodie covered it.\""), .cross("Did {D} strike you?", "\"No. {D} yanked the arm free. {D} did not hit me, and I was not hurt.\""), .cross("Why did {D} give a false name?", "\"I do not know. {D} says {D} did not know I was a deputy. I cannot say what {D} thought.\""), .cross("Was {D} cooperative afterward?", "\"Yes. Once I showed the badge, {D} gave the real name and cooperated.\"")],
