        defendant: [.direct("Please describe your afternoon.", "\"I was skating across a loading dock. I did not know it was off limits, and I was just practicing.\""), .direct("What did you hear?", "\"A stranger in a hoodie shouted. I did not hear the word deputy. I thought it was someone angry at skaters.\""), .direct("Why did you run?", "\"I was startled. A stranger yelled and came toward me, and I did not know who it was.\""), .direct("Why did you pull away from the hand?", "\"I thought a stranger was grabbing me. I did not know it was a deputy, and I pulled away.\""), .direct("Why did you give a false first name?", "\"I was scared. I did not know who I was talking to. I know it was a bad idea.\""), .direct("Looking back, how do you feel about it?", "\"Embarrassed, more than anything. I did not know it was a deputy, and I wish I had stopped.\""), .cross("You ran when someone called out, didn't you?", "\"Yes. I did. I was frightened, and I did not stop.\""), .cross("You gave a false first name, didn't you?", "\"Yes. I did. I know it was wrong, and I gave the real one afterward.\""), .cross("A store clerk says the deputy shouted deputy twice, doesn't the clerk?", "\"The clerk says so. I did not hear it. I may have had headphones on.\""), .cross("The deputy's vest was marked Sheriff, wasn't it?", "\"It was zipped under a hoodie. I did not see it until later.\""), .cross("You pulled your arm away from the deputy, didn't you?", "\"Yes. I did. I did not know who it was.\"")],
        openings: ("A plainclothes deputy responding to a shopping center complaint called out to {D}, who was skating across a loading dock on {DATE}. {D} ran, was caught at a drainage path, pulled away from a hand on the arm, and gave a false first name.", "The defense will present a person who never heard the word deputy, a vest zipped under a hoodie, and a stranger who shouted. A person cannot knowingly flee from someone who is not known to be an officer."),
        closings: ("A deputy who called out twice, a run across the loading dock, an arm yanked free, and a false name. The vest was marked Sheriff, and {D} knew someone was calling.", "A hooded stranger who never said who the stranger was, a vest hidden under a hoodie, and a young person who was startled. The State has not proved that {D} knew the person was a deputy."),
        timeline: [(0, "4 p.m.: the owner reports skaters on the dock."), (0, "4:20 p.m.: the deputy calls out; {DL} runs."), (0, "4:25 p.m.: {DL} pulls free and gives a false name.")],
        identified: "A shopping center lot camera.")

