        state: [E(.document, 3, "Scrap Yard Ticket", "{D}'s ID on a ticket for 95 pounds of coil copper the next morning."), E(.video, 3, "Parking Lot Camera", "A white pickup with a ladder leaves at 4:10 a.m.")],
        defense: [E(.statement, 1, "Demolition Salvage", "{DL} says {D.he} buys salvage from demolition crews.")],
        role: "Church treasurer",
        exam: [.direct("Please tell us about your role at the church.", "\"I am the church treasurer. I manage the budget, pay bills, and keep records of repairs. The church is small, and every dollar counts.\""), .direct("What happened overnight on {DATE}?", "\"Two rooftop air conditioning units were cut open, and their copper coils were taken. The loss was worth $5,400.\""), .direct("What did the parking lot camera show?", "\"A white pickup with a ladder in the bed leaving at 4:10 a.m. The camera does not show a face.\""), .direct("What did the scrap yard record?", "\"A ticket with {D}'s ID for 95 pounds of coil copper the next morning.\""), .direct("What was found in {D}'s truck?", "\"A tubing cutter. Tool marks on the cut lines match it.\""), .direct("What did this cost the church?", "\"$5,400 to replace the coils, plus a week without air conditioning. Our members were uncomfortable, and we had to move services.\""), .cross("Does {D} hold a salvage license?", "\"Yes. {D} holds a salvage license and had a signed purchase from a demolition crew two days earlier.\""), .cross("Did anyone see {D} at the church?", "\"No. No one saw {D}. We have the camera, the ticket, and the tool marks.\""), .cross("Is a white pickup with a ladder common?", "\"Yes. Many contractors drive one. I cannot say the pickup on camera was {D}'s.\""), .cross("Could the copper sold have come from elsewhere?", "\"It could. {D} says {D} buys salvage from demolition crews.\""), .cross("How much copper was in the coils?", "\"I do not know exactly. The scrap ticket is for 95 pounds, which is a plausible match, but I cannot be sure.\"")],
        defenseRole: "Defendant's brother-in-law",
        defenseExam: [.direct("Tell us how you know {D}.", "\"I am {D}'s in-law. We are close, and I have helped {D} with salvage jobs. I know how {D} buys and sells.\""), .direct("What do you know about {D}'s salvage work?", "\"{D} buys from demolition crews and keeps receipts. I have seen the paperwork for many purchases.\""), .direct("What did you see two days before the break-in?", "\"I saw {D} buy a load of coil copper from a demolition crew. I watched the crew sign the receipt.\""), .direct("What kind of person is {D}?", "\"Honest and hard-working. {D} follows the rules and holds a license. I was shocked by the accusation.\""), .direct("Do other people carry tubing cutters?", "\"Yes. Every salvage worker I know does. They are common tools.\""), .direct("What do you think about the case?", "\"I think {D} did what {D} always does. {D} bought copper legitimately and sold it the next morning.\""), .cross("Were you with {D} on the night of the break-in?", "\"No. I was not. I cannot say where {D} was.\""), .cross("Did you see the copper {D} sold?", "\"I saw the load that was bought earlier. I did not see it at the scrap yard.\""), .cross("Is the copper from the church identical to what {D} bought?", "\"I do not know. Coil copper looks much the same, and I did not compare it.\""), .cross("Does {D} drive a white pickup?", "\"Yes. A white pickup with a ladder rack. Many contractors drive that kind.\""), .cross("Did {D} ever mention the church?", "\"No. {D} never mentioned it before the case.\"")],
        theory: ("{D} climbed on a church roof and sold the coils.", "A salvage buyer who did not know the copper was stolen."),
        allocution: "\"I needed money. I'm sorry for the church.\"",
        truths: ("Tool marks on the cut lines match a tubing cutter found in {DL}'s truck.", "{DL} holds a salvage license and had a signed purchase from a demolition crew two days earlier."),
        defendant: [.direct("Tell us about your work.", "\"I buy salvage from demolition crews and resell it at scrap yards. I hold a salvage license, and I keep records of what I buy.\""), .direct("Where did the copper come from?", "\"From a demolition crew. I have a signed purchase from two days earlier. That is the coil I sold.\""), .direct("Did you take the church's coils?", "\"No. I did not. I have never been on the church roof, and I would not steal from a church.\""), .direct("Why did you have a tubing cutter?", "\"It is a normal tool for salvage. I use it often, and many people in my trade carry one.\""), .direct("Why were you at the scrap yard so early?", "\"I sell in the morning, before the lines. That is my normal routine.\""), .direct("How do you feel about being accused?", "\"I am hurt. I do honest work, and now I am accused of stealing from a church.\""), .cross("You sold 95 pounds of coil copper the next morning, didn't you?", "\"Yes. I did. I have a purchase record for it.\""), .cross("Tool marks on the cut lines match your tubing cutter, don't they?", "\"So the lab reports. Many cutters look alike, and I did not use mine on the church.\""), .cross("A white pickup with a ladder was on the camera, wasn't it?", "\"Yes. I own one like it. So do many others.\""), .cross("You buy salvage from demolition crews, don't you?", "\"Yes. I did that here. I have a signed receipt.\""), .cross("You cannot show the demolition site, can you?", "\"I have the receipt and the crew's name. I know it does not prove everything.\"")],
        openings: ("Two rooftop air conditioning units at a small church were cut open overnight on {DATE}, and their copper coils worth $5,400 were taken. A parking lot camera showed a white pickup with a ladder, a scrap yard had bought a load of coil copper that morning from {D}, and tool marks matched a tubing cutter in {D}'s truck.", "The defense will present a licensed salvage buyer, a signed purchase from a demolition crew two days earlier, and a common pickup. Selling copper is not stealing it."),
        closings: ("A white pickup with a ladder, 95 pounds of coil copper sold the next morning under {D}'s ID, and tool marks that match a tubing cutter in {D}'s truck. The church lost $5,400.", "A salvage license, a signed purchase from a demolition crew, and a common tool and pickup. The State has not proved that {D} took the church's coils."),
        timeline: [(-1, "The air conditioners are working Sunday evening."), (0, "4:10 a.m.: a pickup leaves the lot."), (0, "9 a.m.: {DL} sells coil copper."), (1, "The church finds the units cut open.")],
        identified: "A scrap yard ticket and a parking lot camera.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .indifferent)

    static let falseNameDeputyV1 = SmallCases.make(
        key: "story.falseNameDeputy",
        category: .publicOrder,
        headlines: ["Roommate's Name Given at Alarm Call Unravels", "Driver's License Photo Exposes False Identity"],
        law: "obstruction",
        spec: "Willfully and unlawfully delayed and obstructed a public officer by giving a false name during a lawful stop, on {DATE}.",
        ages: 19...50,
        victim: false,
        summary: "A deputy answering a store alarm on {DATE} stopped {D} walking behind the building and asked for a name. {D} gave a roommate's name and birth date. The deputy ran the name and the license photo did not match what the body camera showed. {DL} says {D.he} thought the deputy was making conversation and was free to go.",
        state: [E(.video, 3, "Body Camera", "{D} gives the roommate's name and birth date when asked twice."), E(.document, 2, "License Photo", "The roommate's license photo does not match {D}.")],
        defense: [E(.statement, 1, "Casual Talk", "{DL} says it felt like a casual talk, not a stop.")],
        role: "Sheriff's deputy",
        exam: [.direct("Describe your work as a sheriff's deputy.", "\"I patrol the county and answer alarms at businesses. I walk the perimeter, check doors and windows, and talk to anyone nearby.\""), .direct("Why were you at the store on {DATE}?", "\"A store alarm went off. I responded and checked behind the building.\""), .direct("What did you see?", "\"{D} walking behind the building. I asked {D} for a name.\""), .direct("What name did {D} give?", "\"A roommate's name and birth date. I asked twice, and {D} gave the same answer.\""), .direct("How did you learn it was false?", "\"I ran the name, and the license photo did not match what my body camera showed. The photo belongs to {D}'s roommate.\""), .direct("What did you learn about {D}'s record?", "\"{D} had an outstanding warrant for missing court. That is why giving a false name mattered.\""), .cross("Did you tell {D} to stop?", "\"No. I did not activate lights or give a command to stop. I told {D} that {D} was free to leave.\""), .cross("Was it a stop or a conversation?", "\"It felt like a casual talk. {D} says it felt that way too. I asked for a name as part of the alarm response.\""), .cross("Was {D} told the reason for the questions?", "\"I said I was answering an alarm. I did not say {D} was suspected of anything.\""), .cross("Did {D} try to leave?", "\"No. {D} stayed and gave the name. {D} did not run.\""), .cross("Was {D} detained?", "\"Not formally. I did not block {D}'s path. I did not use force.\"")],
        theory: ("{D} gave a false name to avoid a deputy's check.", "A casual conversation that was not a stop."),
        allocution: "\"I used a name that wasn't mine. I'm sorry.\"",
        truths: ("{DL} had an outstanding warrant for missing court.", "The body camera shows no lights, no command to stop, and a deputy who said {D.he} was free to leave."),
        defendant: [.direct("Tell us what happened that evening.", "\"I was walking behind a building after work. A deputy approached and asked for a name. I thought it was friendly talk.\""), .direct("Why did you give your roommate's name?", "\"I had a warrant for missing court. I was scared, and the name came out. I know it was wrong.\""), .direct("Did the deputy tell you to stop?", "\"No. There were no lights and no command. The deputy said I was free to leave.\""), .direct("Why did you stay?", "\"I thought I was free to go, and I did not want to seem suspicious. I answered the questions.\""), .direct("What did you say about the birth date?", "\"I gave my roommate's birth date. I had memorized it from mail. That was clearly the wrong thing to do.\""), .direct("Looking back, how do you feel about it?", "\"The word for it is stupid. I should have gone to court and told the truth. I made a bad choice out of fear.\""), .cross("You gave a false name, didn't you?", "\"Yes. I did. I was frightened about the warrant.\""), .cross("You gave it twice, didn't you?", "\"Yes. I did. I know it makes it look planned, but I was panicking.\""), .cross("The license photo did not match you, did it?", "\"No. It was my roommate's. I know that proved it was false.\""), .cross("You had a warrant for missing court, didn't you?", "\"Yes. I had missed a hearing. I was ashamed and I did not want to be arrested.\""), .cross("You thought the talk was casual, didn't you?", "\"Yes. It seemed that way. I should have told the truth anyway.\"")],
        openings: ("A deputy answering a store alarm on {DATE} stopped {D} walking behind the building and asked for a name. {D} gave a roommate's name and birth date twice, and the license photo did not match the body camera.", "The defense will present a talk that felt casual, a deputy who said {D} was free to go, and no lights or commands. The State must prove that {D} was lawfully detained when the false name was given."),
        closings: ("A false name and birth date given twice, a roommate's license photo that does not match {D}, and an outstanding warrant for missing court. The body camera shows it.", "A casual talk with no lights, no command to stop, and a deputy who said {D} was free to leave. The State has not proved that {D} was lawfully detained."),
        timeline: [(0, "8:50 p.m.: a store alarm sounds."), (0, "9:05 p.m.: the deputy stops {DL} behind the building."), (0, "9:20 p.m.: the license photo does not match.")],
        identified: "A body camera and a license photo.",
        genders: ["D": .male])

    static let streetRifleV1 = SmallCases.make(
        key: "story.streetRifle",
        category: .violent,
        headlines: ["Teen Guarding Gas Station in Ice Storm Blackout Shoots Man at Pumps", "Cousin's Request or Vigilante Night?"],
        law: "murder2",
        threshold: 1,
        spec: "Killed {V} with a rifle, with malice.",
        ages: 19...19,
        victim: true,
        summary: "During a week-long ice storm blackout, {D} sat in a lawn chair at {D.his} cousin's gas station on {DATE} with a deer rifle, guarding the pumps. Around midnight {V} came with a gas can and a pry bar, and the two argued. {V} stepped toward {D} and {D} fired once, killing {V}. The State says {D} sought a confrontation and created the danger. The defense says {V} advanced with the bar raised.",
        state: [E(.video, 3, "Pump Camera", "Grainy night footage: {V} approaches the lawn chair and steps closer; one flash; {V} falls."), E(.statement, 2, "Text to a Friend", "Hours earlier, {D} wrote: 'Hope somebody tries it tonight.'"), E(.document, 2, "Emergency Order", "A countywide order asked residents to stay indoors after dark during the outage.")],
        defense: [E(.physical, 3, "Pry Bar", "A two-foot pry bar lay beside {V}'s hand."), E(.document, 2, "Cousin's Request", "The cousin texted {D}: 'Can you sit at the station tonight? Nobody's coming.'"), E(.statement, 1, "911 Call", "{D} called 911 within a minute and waited with the rifle on the ground.")],
        role: "Lead detective",
        exam: [.direct("Tell the jury about your work as lead detective.", "\"I lead homicide investigations. I examine scenes, review video, and interview witnesses, and I work with prosecutors on charging decisions.\""), .direct("What was the situation in the county that week?", "\"A week-long ice storm blackout. A countywide emergency order asked residents to stay indoors after dark during the outage.\""), .direct("What did {D} do on {DATE}?", "\"{D} sat in a lawn chair at a cousin's gas station with a deer rifle, guarding the pumps.\""), .direct("What happened around midnight?", "\"{V} came with a gas can and a pry bar, and the two argued. {V} stepped toward {D}, and {D} fired once, killing {V}.\""), .direct("What did the pump camera show?", "\"Grainy night footage. {V} approaches the lawn chair and steps closer, there is one flash, and {V} falls.\""), .direct("What did {D} text earlier that day?", "\"Hours earlier, {D} wrote, Hope somebody tries it tonight. A friend later produced texts where {D} wanted to catch somebody at the pumps.\""), .cross("Why was {D} at the station?", "\"The cousin texted, Can you sit at the station tonight? Nobody's coming. {D} was asked to be there.\""), .cross("What was beside {V}'s hand?", "\"A two-foot pry bar. It lay beside {V}'s hand when we arrived.\""), .cross("What does the passing deputy's dash camera show?", "\"{V} lifting the bar before the shot. That supports {D}'s account.\""), .cross("What did {D} do after the shot?", "\"{D} called 911 within a minute and waited with the rifle on the ground.\""), .cross("Did {D} threaten {V} aloud?", "\"I did not hear a recording of a threat. The two argued, and I do not have the words.\"")],
        defenseRole: "Use-of-force instructor",
        defenseExam: [.direct("What do you do as a use-of-force instructor?", "\"I train civilians and officers on when force is lawful. I teach about threat perception, distance, and reaction time.\""), .direct("What did you review in this case?", "\"The pump camera, the passing deputy's dash camera, the pry bar, and the timeline of the shot.\""), .direct("What does the dash camera show about {V}?", "\"{V} lifting the bar before the shot. That is a significant fact for threat assessment.\""), .direct("How quickly can a person react to a raised bar at close range?", "\"In under a second. At a distance of a few feet, a person has very little time to decide.\""), .direct("Can a person be afraid even if the person created some of the situation?", "\"Yes. Fear is a human reaction. Whether it was reasonable is a legal question, but the fear can be real.\""), .direct("What would you expect from a person who intended to kill?", "\"A person might fire more than once, or flee. {D} fired once, called 911, and waited. That fits a defensive reaction.\""), .cross("Did {D} have a duty to retreat?", "\"The law in this state does not require retreat in many places. But {D} chose to be at the station with a rifle.\""), .cross("Did {D}'s texts matter?", "\"They matter. {D} wrote that {D} hoped somebody tried it. A jury may see that as showing intent.\""), .cross("Was {V} armed with a firearm?", "\"No. {V} had a pry bar. A pry bar can cause serious harm, but it is not a gun.\""), .cross("Was {D} in danger before {V} lifted the bar?", "\"I cannot say. The video is grainy, and I rely on the dash camera for that moment.\""), .cross("Does the order to stay indoors change the analysis?", "\"It may change how reasonable it was to be there. It does not change what happened when {V} advanced.\"")],
        theory: ("{D} wanted a confrontation and shot someone who came for gas.", "A teenager guarding a family station was rushed with a pry bar."),
        allocution: "\"I didn't want anyone to die. I thought the bar was coming down on me.\"",
        truths: ("A friend later produced texts where {D} wanted to 'catch somebody' at the pumps.", "A passing deputy's dash camera showed {V} lifting the bar before the shot."),
        defendant: [.direct("Tell the jury why you were at the station.", "\"My cousin asked me to sit at the station because there were break-ins. I took my deer rifle, and I wanted to protect the pumps.\""), .direct("What happened when {V} arrived?", "\"{V} came with a gas can and a pry bar. We argued. I told {V} to stay back, and {V} did not.\""), .direct("Why did you fire?", "\"{V} stepped toward me with the bar raised. I was afraid for my life, and I fired once.\""), .direct("What did you do right after?", "\"I called 911 within a minute. I put the rifle on the ground and waited for deputies.\""), .direct("What did you mean by the text, Hope somebody tries it tonight?", "\"It was a joke. I was nervous and I was trying to feel braver. I did not mean I wanted a fight.\""), .direct("How do you feel about what happened?", "\"Right now I feel horrible. {V} died, and I will carry that. I wish I had never gone to the station.\""), .cross("You wrote that you hoped somebody tries it tonight, didn't you?", "\"Yes. I did. I realize how that sounds. I did not mean it the way it reads.\""), .cross("You wanted to catch somebody at the pumps, didn't you?", "\"I told a friend that. I meant I wanted to stop thieves, not to hurt anyone.\""), .cross("The county had asked residents to stay indoors after dark, hadn't it?", "\"Yes. I knew. I went to protect my cousin's station, and I know that is part of the problem.\""), .cross("You fired a deer rifle at close range, didn't you?", "\"Yes. {V} was only a few feet away. I fired once.\""), .cross("{V} had not touched you, had {V}?", "\"No. {V} had not touched me. {V} was close and raised the bar.\"")],
        openings: ("During a week-long ice storm blackout, {D} sat in a lawn chair at a cousin's gas station on {DATE} with a deer rifle, guarding the pumps. Around midnight {V} came with a gas can and a pry bar, the two argued, and {D} fired once, killing {V}.", "The defense will present a pry bar raised toward {D}, a passing deputy's dash camera that shows it, a cousin who asked {D} to sit at the station, and a prompt call to 911. {D} fired in fear for {D}'s life."),
        closings: ("A rifle in a lawn chair at midnight, a text that said hope somebody tries it tonight, a county order to stay indoors, and one shot that killed {V}. The State says {D} sought the confrontation.", "A pry bar raised in the dash camera, a call to 911 within a minute, and a person who waited with the rifle on the ground. The State has not proved that {D} did not act in self-defense."),
        timeline: [(-4, "An ice storm knocks out power across the county."), (-1, "Two thefts at the pumps are reported."), (0, "6 p.m.: {D} texts a friend."), (0, "11:58 p.m.: one shot is fired."), (0, "11:59 p.m.: {D} calls 911.")],
        identified: "{D} called 911 and identified as the shooter.",
        aggravating: ["The offense occurred during a declared emergency"],
        mitigating: ["{DL} was a teenager", "{DL} called 911 and surrendered immediately"],
        mood: .divided,
        doctrines: ["selfDefense", "imperfectSelfDefense"])

    static let couponStackV1 = SmallCases.make(
