        state: [E(.digital, 4, "Smart Lock Log", "The boathouse lock records {D}'s personal code at 8:12 p.m. and no exit until the 911 call.", .search), E(.document, 3, "Forged Loan Papers", "Loan documents carried {V}'s forged signature; {V} had asked the lender for copies that week."), E(.digital, 2, "Phone Movement", "{D}'s phone shows no movement at the marina from 8:00 to 8:20 p.m., then a burst of steps.", .search)],
        defense: [E(.document, 3, "No Weapon", "No weapon was recovered and no residue was found on {D}'s clothing."), E(.document, 2, "Fired Yard Hand", "A yard hand fired two weeks earlier for theft had threatened {V}."), E(.document, 1, "Shared Code", "Boathouse codes were shared with six staff members.")],
        role: "SBI agent",
        exam: [.direct("Describe your work as an SBI agent.", "\"I investigate homicides and financial crimes for the State Bureau of Investigation. I examine scenes, records, and digital access logs.\""), .direct("What happened at 10:05 p.m. on {DATE}?", "\"{D}, who owns a well-known boat dealership at a lake, called 911 to say {V}, {D}'s spouse, had been shot in the family boathouse.\""), .direct("Where did {D} say {D} had been?", "\"At the marina office all evening. {D} said {D} was not at the boathouse.\""), .direct("What did the smart lock record?", "\"{D}'s personal code entering at 8:12 p.m. That is nearly two hours before the call.\""), .direct("What did you learn about loan papers?", "\"Loan documents carried a forged signature of {V}. {V} had asked the lender for copies that week.\""), .direct("What was found in the locker?", "\"A cleaned pistol in a storage locker rented in {D}'s business name.\""), .cross("Was a weapon recovered at the boathouse?", "\"No. No weapon was recovered, and no residue was found on {D}'s clothing.\""), .cross("Who else had a code?", "\"Boathouse codes were shared with six staff members. Several people could have entered.\""), .cross("Who had threatened {V}?", "\"A yard hand fired two weeks earlier for theft. That person had threatened {V}.\""), .cross("What was later found about the yard hand?", "\"The yard hand was arrested later with a pistol that matched the bullet and a missing outboard motor from the marina.\""), .cross("Does the locker pistol match the bullet?", "\"I cannot say. It had been cleaned. I do not have a match to that pistol.\"")],
        defenseRole: "Locksmith for the defense",
        defenseExam: [.direct("Describe your work as a locksmith.", "\"I install and service smart locks. I understand how access logs work and how codes can be shared or copied.\""), .direct("What does the smart lock record?", "\"A code and a time. It does not record who typed the code. It only knows the code was entered.\""), .direct("How could someone else use a personal code?", "\"If they saw it, were told it, or guessed it. Staff often share codes, and I have seen many that were widely known.\""), .direct("What did you see about the boathouse codes?", "\"They were shared with six staff members. That means any of seven people could enter with someone's code.\""), .direct("What do you think about the 8:12 p.m. entry?", "\"It shows a code. It does not prove that {D} typed it. I cannot say who did.\""), .direct("Can a code be reset or logged incorrectly?", "\"Yes. A glitch or a reset can cause a wrong log. I did not find a glitch here, but I cannot rule it out.\""), .cross("Did {D} know the code?", "\"Yes. It is {D}'s personal code. {D} would know it better than anyone.\""), .cross("Did you test the lock?", "\"I reviewed the log and the lock. I did not find tampering. I cannot say who entered.\""), .cross("Did {D} share the code?", "\"I do not know. {D} may have. I only know that staff members had shared codes.\""), .cross("Could {D} have entered at 8:12?", "\"Yes. It is possible. I cannot rule it out.\""), .cross("Is the log reliable?", "\"Generally. I found no sign of error. But a log is not a witness.\"")],
        theory: ("{D} faced exposure over forged loan papers and shot a spouse in the boathouse.", "A shared code, no weapon, and an angry former employee."),
