        identified: "A smart lock log placed {D} at the boathouse.",
        aggravating: ["The offense was committed to avoid exposure of other crimes"],
        mitigating: ["No prior violent record"],
        mood: .wantsConviction,
        impact: "Find out who did this and make them pay.")

