    static let nurseryNightV1 = SmallCases.make(
        key: "story.nurseryNight",
        category: .violent,
        headlines: ["Parent Called Own Mother Before Deputies Found Two Children Dead", "ER Visit Days Before Raises Insanity Question"],
        law: "murder1",
        threshold: 3,
        spec: "Killed the defendant's two young children with malice, premeditation, and deliberation.",
        ages: 28...38,
        victim: false,
        summary: "On the night of {DATE}, {D} was alone with {D.his} young children while the spouse was away on a work trip. Just after midnight {D} called {D.his} own mother and said, \"I put them to sleep so they can't be taken.\" The mother called 911. Deputies found the two older children dead in their beds and the baby unharmed. Eleven days earlier {D} had gone to an emergency room describing voices about the children and was sent home with a referral. The State says {D} planned the night. The defense says {D} was in a postpartum psychosis.",
        state: [E(.statement, 3, "Call to the Mother", "{D} told {D.his} mother, 'I put them to sleep so they can't be taken,' and 'I know how this looks.'"), E(.digital, 2, "Phone Searches", "Three days earlier, {D} searched how long sleeping medication lasts.", .search), E(.forensic, 3, "Medical Examiner", "Both children died without signs of a struggle.")],
        defense: [E(.document, 3, "Emergency Room Chart", "Eleven days earlier: 'hearing voices about the children, not sleeping, denies plan, refer to psychiatry.'"), E(.document, 2, "Spouse's Texts", "Days before: '{D} says the house is being watched and won't let anyone near the kids.'"), E(.document, 2, "No Prior History", "No criminal or psychiatric history before the birth.")],
        role: "Lead detective",
        exam: [.direct("What can you tell us about your work as the lead detective?", "\"I lead investigations into deaths of children. I review medical records, scenes, and statements, and I try to understand what happened.\""), .direct("What happened on the night of {DATE}?", "\"{D} was alone with {D}'s young children while the spouse was away on a work trip. Just after midnight, {D} called {D}'s own parent.\""), .direct("What did {D} say on the call?", "\"I put them to sleep so they can't be taken. {D} also said, I know how this looks.\""), .direct("What did deputies find?", "\"The two older children had died in their beds, and the baby was unharmed. The medical examiner found no signs of a struggle.\""), .direct("What did the emergency room chart show?", "\"Eleven days earlier, {D} went to an emergency room describing voices about the children. The chart reads hearing voices about the children, not sleeping, denies plan, refer to psychiatry.\""), .direct("What did the spouse's texts show?", "\"Days before, the spouse texted that {D} said the house was being watched and would not let anyone near the kids.\""), .cross("Did {D} have a prior history?", "\"No. There was no criminal or psychiatric history before the birth.\""), .cross("Was the referral urgent?", "\"The referral was flagged routine by mistake instead of urgent. That is an important fact.\""), .cross("Did {D} call for help?", "\"{D} called {D}'s parent, who called 911. {D} did not call 911 directly.\""), .cross("What did a journal show?", "\"A journal found after the trial showed {D} wrote about getting free of motherhood before any symptoms. I do not know when it was written.\""), .cross("Did {D} resist the deputies?", "\"No. {D} was calm and cooperative. {D} said {D} knew how it looked.\"")],
        defenseRole: "Perinatal psychiatrist for the defense",
        defenseExam: [.direct("Describe your work as a perinatal psychiatrist.", "\"I treat mental illness related to pregnancy and childbirth. I evaluate postpartum depression and psychosis and testify about how they affect behavior.\""), .direct("What is postpartum psychosis?", "\"A severe illness that can occur after childbirth. It can cause delusions, hallucinations, and loss of contact with reality.\""), .direct("What did you review in this case?", "\"The emergency room chart, the spouse's texts, the call to the parent, and {D}'s history. I also interviewed {D}.\""), .direct("What did the chart suggest?", "\"Voices about the children, not sleeping, and a referral to psychiatry. Those are warning signs of psychosis.\""), .direct("What did the call suggest?", "\"A delusional belief that the children would be taken. The statement fits the illness, not a plan to harm.\""), .direct("What is the risk when a referral is marked routine?", "\"The patient may not be seen quickly. In this case, the mistake delayed care when care was urgent.\""), .cross("Did {D} know right from wrong?", "\"That is a legal question. I can say {D} was seriously ill. I cannot say what {D} understood at every moment.\""), .cross("Could the journal suggest earlier planning?", "\"It suggests earlier conflict about motherhood. It does not show a plan, and it is not a symptom of psychosis.\""), .cross("Did {D} deny a plan at the ER?", "\"Yes. {D} denied it. People with psychosis often do not recognize what is happening.\""), .cross("Is the disease always visible?", "\"No. It can look like calm. {D} was calm on the call, which is not unusual.\""), .cross("Does this illness excuse what happened?", "\"I do not decide that. I only explain what happens to a person in psychosis, and the jury decides the rest.\"")],
        theory: ("{D} chose a night alone and carried out a plan, knowing how it would look.", "A psychosis that sent {D} to an ER eleven days earlier and turned love into a delusion."),
        allocution: "\"I would trade my life for theirs. I didn't understand until it was over.\"",
        truths: ("A journal found after the trial showed {D} wrote about 'getting free' of motherhood before any symptoms.", "The ER's psychiatric referral was flagged 'routine' by mistake instead of 'urgent.'"),
        defendant: [.direct("Describe your children for the jury.", "\"I loved them more than anything. I was a new parent again, with a baby, and I was exhausted and afraid.\""), .direct("What was happening before that night?", "\"I was not sleeping. I heard voices that said my children would be taken. I went to an emergency room, and I was sent home.\""), .direct("What did you believe that night?", "\"I believed they were in danger. I believed people were coming to take them, and I thought I had to protect them.\""), .direct("Why did you call your parent?", "\"Because I was scared. I said what I believed, and my parent called 911.\""), .direct("What do you understand now?", "\"That I was ill. I was not thinking clearly. I would never have hurt them if I had been well.\""), .direct("How do you feel about what happened?", "\"I am devastated. I lost my children, and I live with it. I wish I had gotten help sooner.\""), .cross("You said I put them to sleep so they can't be taken, didn't you?", "\"Yes. I said that. I believed it at that moment.\""), .cross("You said I know how this looks, didn't you?", "\"Yes. Part of me knew. Another part was lost.\""), .cross("The two older children died in their beds, didn't they?", "\"Yes. I know. I cannot say more about that night.\""), .cross("You wrote about getting free of motherhood in a journal, didn't you?", "\"Yes. I wrote that before the voices. I did not mean I would harm anyone.\""), .cross("You denied having a plan at the emergency room, didn't you?", "\"Yes. I did. I did not have one then. I was afraid and confused.\"")],
        openings: ("On the night of {DATE}, {D} was alone with {D}'s young children while the spouse was away on a work trip. Just after midnight {D} called {D}'s own parent and said, I put them to sleep so they can't be taken, and deputies found the two older children dead and the baby unharmed.", "The defense will present an emergency room visit eleven days earlier for voices about the children, a referral that was marked routine by mistake, and a perinatal psychiatrist who will explain postpartum psychosis. {D} was seriously ill."),
        closings: ("A call that said I put them to sleep so they can't be taken, two children who died without a struggle, and a journal that wrote about getting free of motherhood. The State says {D} planned the night.", "Voices about the children, a referral marked routine instead of urgent, and a person who had no prior history. The State has not proved that {D} acted with the required intent while in psychosis."),
        timeline: [(-120, "The third child is born."), (-11, "{DL} goes to an ER describing voices about the children."), (-3, "{DL}'s phone searches about sleeping medication."), (0, "12:10 a.m.: {DL} calls {D.his} mother."), (0, "12:35 a.m.: deputies find the children."), (21, "Defense gives notice of an insanity defense.")],
        identified: "{D}'s own call to {D.his} mother.",
        aggravating: ["The victims were very young children"],
        mitigating: ["{DL} suffered from a severe mental illness that significantly reduced culpability", "No prior criminal record", "{DL} sought medical help before the offense"],
        mood: .divided,
        doctrines: ["insanity", "burdenOfProof"],
        genders: ["D": .female])

    static let leagueTreasurerV1 = SmallCases.make(
        key: "story.leagueTreasurer",
        category: .whiteCollar,
        headlines: ["Band Boosters Lose Trip Money; Bus Company Cancels", "Treasurer's Card Purchases Appear in Booster Account Records"],
