        state: [E(.document, 3, "Account Statements", "Eleven transfers to {D}'s personal card over two months, totaling $3,600."), E(.document, 2, "Bus Company Notice", "The charter was canceled for nonpayment of the deposit.")],
        defense: [E(.statement, 1, "Uniform Costs", "{DL} says the money repaid uniforms bought out of pocket.")],
        role: "Booster club president",
