        spec: "Carried a concealed handgun, a .38 revolver, on and about {D.his} person without a permit, on {DATE}.",
        ages: 24...66,
        victim: false,
        summary: "A screening deputy at the courthouse entrance saw the shape of a revolver on the X-ray belt on {DATE}. It was in a canvas tote bag carried by {D}, who had come for traffic court. {D} had no permit. {DL} says {D.he} had picked up the revolver from a gunsmith that morning and forgot it was in the bag.",
        state: [E(.physical, 3, "The Revolver", "A loaded .38 revolver in a zippered pocket of a canvas tote bag.", .search), E(.document, 2, "Permit Check", "No concealed handgun permit on file for {D}.")],
        defense: [E(.statement, 1, "Gunsmith Pickup", "{DL} says the revolver came back from repair that morning.")],
        role: "Courthouse screening deputy",
        exam: [.direct("What do you do as a courthouse screening deputy?", "\"I run the X-ray belt and the metal detector at the courthouse entrance. I watch every bag and coat that goes through, and I stop anything that looks like a weapon.\""), .direct("What did you see on {DATE}?", "\"The shape of a revolver on the X-ray belt. It was in a canvas tote bag carried by {D}.\""), .direct("Why was {D} at the courthouse?", "\"{D} had come for traffic court. {D} was one of many visitors that morning.\""), .direct("What did you do?", "\"I stopped the bag, opened it, and found the revolver. I secured it and called a supervisor.\""), .direct("Did {D} have a permit?", "\"No. A permit check found no concealed handgun permit on file for {D}.\""), .direct("What did {D} say?", "\"{D} said {D} had picked the revolver up from a gunsmith that morning and forgot it was in the bag.\""), .cross("Did the gunsmith confirm the pickup?", "\"A gunsmith receipt shows {D} picked up the revolver at 9:15 that morning. That matches what {D} said.\""), .cross("Was the revolver loaded?", "\"I do not recall. I secured it and the supervisor checked. I did not see {D} try to use it.\""), .cross("Did {D} try to hide the gun?", "\"No. {D} put the bag on the belt like everyone else. {D} did not try to get around the screening.\""), .cross("Was {D} cooperative?", "\"Yes. {D} was polite and embarrassed. {D} said it was a mistake.\""), .cross("Did {D} threaten anyone?", "\"No. There was no threat. {D} was just there for traffic court.\"")],
        theory: ("{D} carried a loaded revolver in a bag into a courthouse without a permit.", "A person who forgot a gun in a bag after a gunsmith errand."),
