        timeline: [(0, "9:15 a.m.: {DL} picks up the revolver."), (0, "10 a.m.: {DL} arrives at the courthouse."), (0, "10:05 a.m.: the X-ray shows the revolver.")],
        identified: "A courthouse X-ray screening.",
        genders: ["D": .female])

    static let voicemailThreatV1 = SmallCases.make(
        key: "story.voicemailThreat",
        category: .violent,
        headlines: ["Neighbor Charged Over Text: 'Cut That Oak Down or I'll Cut You'", "Leaning Oak Sparks Threat Case"],
        law: "communicatingThreats",
        threshold: 4,
        spec: "Willfully threatened to physically injure {V} in a text message, in a manner that a reasonable person would believe the threat was likely to be carried out.",
        ages: 70...70,
        victim: true,
        summary: "A large oak on {V}'s side leaned toward {D}'s roof. On {DATE} {D} texted {V}: \"Cut that oak down by Friday or I will cut you. I have the saw and nothing to lose.\" {V} called deputies. {DL} owns a chainsaw and had cut down a tree on the line the year before. {DL} says the message meant a lawsuit and the saw line was a clumsy joke.",
        state: [E(.digital, 3, "Text Message", "'Cut that oak down by Friday or I will cut you. I have the saw and nothing to lose.'"), E(.physical, 2, "Chainsaw", "A chainsaw in {D}'s shed, surrendered voluntarily."), E(.document, 1, "Earlier Complaint", "{V} had reported {D} for trimming over the line.")],
        defense: [E(.document, 2, "Arborist Report", "A licensed arborist found the oak is leaning toward {D}'s roof."), E(.document, 2, "Insurance Letter", "{D}'s insurer warned about the tree and sent a letter to {V}."), E(.document, 1, "No Approach", "{D} never entered {V}'s yard after the message.")],
        role: "Neighbor",
        exam: [.direct("Please describe your yard and the oak.", "\"I live next to {D}. A large oak on my side leans toward {D}'s roof. We have talked about it for a while.\""), .direct("What did {D} text on {DATE}?", "\"Cut that oak down by Friday or I will cut you. I have the saw and nothing to lose.\""), .direct("How did you feel when you read it?", "\"Frightened. I did not know if {D} meant it. I called deputies right away.\""), .direct("What do you know about {D}'s chainsaw?", "\"{D} owns a chainsaw and had cut down a tree on the line the year before. {D} surrendered the saw voluntarily.\""), .direct("What earlier complaint had you made?", "\"I had reported {D} for trimming over the line. That began the dispute.\""), .direct("Did {D} come into your yard after?", "\"No. {D} never entered my yard after the message. {D} stayed away.\""), .cross("What did the arborist report say?", "\"A licensed arborist found the oak leans toward {D}'s roof. The lean is real.\""), .cross("Did {D}'s insurer write to you?", "\"Yes. {D}'s insurer warned about the tree and sent me a letter.\""), .cross("Did {D} say what the text meant?", "\"{D} says it meant a lawsuit, and the saw line was a clumsy joke.\""), .cross("Did you delete a second text?", "\"Yes. I deleted a text that read, I know when you're alone. It was recovered from the carrier.\""), .cross("Was {D} on new medication?", "\"I understand {D}'s doctor confirmed a new medicine that month caused irritability and confusion.\"")],
        defenseRole: "Arborist",
        defenseExam: [.direct("How would you describe your job as an arborist?", "\"I am a licensed arborist. I assess trees for health, lean, and risk, and I write reports for owners and insurers.\""), .direct("What did you find about the oak?", "\"It leans toward {D}'s roof. The lean is real and the risk of failure is meaningful in a storm.\""), .direct("How serious is that risk?", "\"It is a hazard. A large oak with that lean can fall in a strong wind, and it can damage a roof and injure people.\""), .direct("Who is responsible for such a tree?", "\"Usually the owner of the land where it stands. That is {V}. I explained that in my report.\""), .direct("What did the insurer do?", "\"It sent a letter about the tree. Insurers often do that when a tree threatens a neighbor's property.\""), .direct("How does that bear on {D}'s concern?", "\"It shows {D}'s concern was reasonable. A person in {D}'s position would be worried, and might act poorly out of fear.\""), .cross("Did you speak to {D} about the text?", "\"No. I only reviewed the tree. I did not discuss the messages.\""), .cross("Does a leaning tree justify a threat?", "\"No. It does not. I only say the concern about the tree was real.\""), .cross("Did {D} ask you to cut the tree?", "\"No. {D} asked me to assess it. I gave a report and a recommendation.\""), .cross("Did {V} respond to the report?", "\"I do not know. I gave the report to {D} and the insurer. I do not know what happened next.\""), .cross("Could a tree be removed safely?", "\"Yes. A professional crew can remove it. The owner must authorize it.\"")],
        theory: ("{D} named a saw and nothing to lose in a text about a tree.", "An old neighbor with a real roof worry and clumsy words."),
        allocution: "\"I said a stupid thing in anger. I was never going to hurt anyone.\"",
        truths: ("A second text, deleted by {V} and recovered from the carrier, read, 'I know when you're alone.'", "{D}'s doctor later confirmed a new medicine that month caused irritability and confusion."),
        defendant: [.direct("Tell us about the tree.", "\"The oak leans toward my roof. I worried it would fall. My insurer warned about it and wrote to {V}.\""), .direct("Why did you send that text?", "\"I was frustrated. I meant I would sue if the oak was not cut. The saw line was a clumsy joke.\""), .direct("Did you mean to hurt {V}?", "\"No. I never would. I never entered {V}'s yard, and I did not threaten {V}.\""), .direct("What about the second text?", "\"I wrote that I knew when {V} was alone. I meant when {V} was home to talk. It was poorly worded.\""), .direct("What was happening with your health?", "\"A new medicine that month caused irritability and confusion. My doctor confirmed it. I was not myself.\""), .direct("How has this affected you?", "\"Mostly I feel ashamed. I frightened a neighbor. I did not mean to, and I am deeply sorry.\""), .cross("You wrote that you would cut {V}, didn't you?", "\"Yes. I wrote that. It reads terribly, and I regret it a lot.\""), .cross("You have a chainsaw, don't you?", "\"Yes. I do. I surrendered it voluntarily.\""), .cross("You cut down a tree on the line last year, didn't you?", "\"Yes. I did. It was a dispute over the line, and it did not go well.\""), .cross("You wrote that you know when {V} is alone, didn't you?", "\"Yes. I did. I did not mean a threat, but I see how it reads.\""), .cross("You wrote that you had nothing to lose, didn't you?", "\"Yes. I was frustrated and scared of the tree. It was an exaggeration.\"")],
        openings: ("A large oak on {V}'s side leaned toward {D}'s roof. On {DATE}, {D} texted {V}: Cut that oak down by Friday or I will cut you. I have the saw and nothing to lose. A second text, deleted by {V} and recovered from the carrier, read, I know when you're alone.", "The defense will present an oak that leans toward {D}'s roof, an insurer's letter, a doctor who confirmed that a new medicine caused irritability and confusion, and a clumsy joke. {D} never approached {V}."),
        closings: ("A text that said I will cut you, a second text that said I know when you're alone, a chainsaw in {D}'s shed, and an earlier complaint. {V} was afraid.", "A real hazard from a leaning oak, a medicine that caused confusion, and a person who never entered {V}'s yard. The State has not proved that {D} meant to threaten {V}."),
        timeline: [(-30, "{DL} reports the leaning oak to an insurer."), (-14, "{V} reports {DL} for trimming over the line."), (0, "The text is sent; {V} calls deputies."), (1, "{DL} consults a lawyer.")],
        identified: "{D}'s own text message.",
        mitigating: ["No prior criminal record", "The defendant has a support system in the community"],
        mood: .indifferent,
        impact: "I still check the yard before I let the dog out.")

    static let investmentClubV1 = SmallCases.make(
        key: "story.investmentClub",
        category: .whiteCollar,
        headlines: ["Church Members' House-Flipping Fund Owned No Houses", "County Deed Search Shows No Purchases"],
        law: "securitiesFraud",
        threshold: 7,
        spec: "Obtained $55,000 from {V}, an investor, by false statements about securities, on {DATE}.",
        ages: 35...65,
        victim: true,
        summary: "{D} sold shares in a house-flipping fund to church members, promising a share of resale profits. {V} and others put in $55,000. A deed search showed the fund never bought a property. The money paid down a restaurant debt. {DL} says the first two houses fell through when appraisals came in low.",
        state: [E(.document, 3, "Deed Search", "No property was ever bought in the fund's name."), E(.document, 3, "Bank Records", "Transfers from the fund to a restaurant supplier."), E(.document, 2, "Glossy Prospectus", "A brochure showing houses {D} did not own.")],
        defense: [E(.statement, 1, "Low Appraisals", "{DL} says two purchases failed on appraisals."), E(.document, 2, "Contract Draft", "A draft purchase contract for one house.")],
        role: "Investor",
        exam: [.direct("Please describe your church and the fund.", "\"I belong to the church where {D} sold shares in a house-flipping fund. I trusted {D} because of our shared faith.\""), .direct("What did {D} promise?", "\"A share of resale profits. {D} showed a glossy prospectus with pictures of houses.\""), .direct("How much did you invest?", "\"{V} and others put in $55,000. I contributed part of my savings.\""), .direct("What did you learn about the fund?", "\"A deed search showed no property was ever bought in the fund's name.\""), .direct("What did the bank records show?", "\"Transfers from the fund to a restaurant supplier. The money paid down a restaurant debt.\""), .direct("How did this affect you?", "\"I lost my savings. I felt betrayed by someone from my church.\""), .cross("Did {D} show you houses?", "\"Pictures in a brochure. I did not tour any houses, and I cannot say whether {D} owned them.\""), .cross("Did {D} sign offers on houses?", "\"I heard that two offers fell through on low appraisals. I did not see them myself.\""), .cross("Did you read the paperwork before investing?", "\"I read the glossy prospectus. I did not read the fine print, and I did not ask for a lawyer.\""), .cross("Was the fund registered?", "\"I do not know. I did not check. I trusted {D} because of our church.\""), .cross("Did {D} promise a guaranteed return?", "\"{D} promised a share of resale profits. I do not recall the word guaranteed.\"")],
        defenseRole: "Real estate agent",
        defenseExam: [.direct("What do you do as a real estate agent?", "\"I help clients buy and sell houses. I write offers, work with appraisers, and see why deals fall through.\""), .direct("What do you know about {D}'s offers?", "\"{D} signed two offers that collapsed on low appraisals. I handled both. They were real offers.\""), .direct("How common are low appraisals?", "\"Fairly common in a changing market. A low appraisal can kill a deal when the buyer needs a loan.\""), .direct("Did {D} seem serious about the plan?", "\"Yes. {D} looked at several houses and asked many questions. I thought {D} was sincere.\""), .direct("Did {D} mention the fund?", "\"Sometimes. {D} said the fund was backing the purchases. I did not see the fund's books.\""), .direct("What would you tell the jury about the market?", "\"It was a hard time to flip houses. Prices were uncertain, and some deals failed even with good intentions.\""), .cross("Did {D} ever close on a house?", "\"Not with me. Both offers failed. I do not know of another.\""), .cross("Did you know about the restaurant debt?", "\"No. I did not. I only knew about the house offers.\""), .cross("Did you see the prospectus?", "\"I saw a brochure. I did not check whether the houses were owned by the fund.\""), .cross("Could {D} have bought houses with the investors' money?", "\"I do not know. I did not see money moved. I only know the offers failed.\""), .cross("Did {D} tell you where the money came from?", "\"Not in detail. I understood it was from a group of investors.\"")],
        theory: ("{D} sold shares in houses that were never bought.", "A flip that failed on appraisals."),
        allocution: "\"I'm sorry. I lost control of the money.\"",
        truths: ("{DL} texted a friend, 'the church money will cover the restaurant.'", "The agent confirmed two signed offers by {DL} that collapsed on low appraisals."),
        defendant: [.direct("Please describe your plan.", "\"I planned to buy houses, fix them, and sell them for profit. Church members trusted me and invested.\""), .direct("What happened to the first two houses?", "\"Two purchases fell through when appraisals came in low. I had signed offers, and the deals collapsed.\""), .direct("Why did the money go to a restaurant supplier?", "\"I used some to pay down a restaurant debt. I texted a friend that the church money would cover the restaurant.\""), .direct("Did you plan to buy houses with all of the money?", "\"I meant to. I thought I could repay the restaurant first. I know that was wrong.\""), .direct("What about the brochure?", "\"It showed houses I did not own. I used pictures of homes I wanted to buy.\""), .direct("How are you coping with what happened?", "\"Mostly I feel ashamed. I misused people's money. I am sorry, and I will try to repay it.\""), .cross("The fund never bought a property, did it?", "\"No. Two offers fell through, and then I stopped. I know that is the problem.\""), .cross("The money paid down a restaurant debt, didn't it?", "\"Yes. Some did. I used church money for that, and I should not have.\""), .cross("You texted that the church money will cover the restaurant, didn't you?", "\"Yes. I did. I know how it reads.\""), .cross("Your brochure showed houses you did not own, didn't it?", "\"Yes. They were houses I hoped to buy. I should have said so.\""), .cross("$55,000 is not coming back, is it?", "\"Not yet. I know I owe it. I will try to repay.\"")],
        openings: ("{D} sold shares in a house-flipping fund to church members, promising a share of resale profits. {V} and others put in $55,000, a deed search showed the fund never bought a property, and the money paid down a restaurant debt.", "The defense will present two signed offers that collapsed on low appraisals, an agent who handled both, and a fund that meant to buy houses. {D} did not set out to take the money."),
        closings: ("$55,000 from church members, a glossy brochure of houses {D} did not own, no deeds, and transfers to a restaurant supplier. A text said the church money will cover the restaurant.", "Two real offers that failed on low appraisals and a fund that meant to buy houses. The State must prove that {D} meant to defraud from the start."),
        timeline: [(-240, "The fund forms."), (-120, "{V} invests."), (0, "{V} asks for a deed copy."), (10, "The deed search finds none.")],
        identified: "A county deed search and bank records.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "Our savings were gone.")

    static let guitarPawnedV1 = SmallCases.make(
        key: "story.guitarPawned",
        category: .property,
        headlines: ["Bandmate's Amp and Pedalboard Listed Online While He Was Away", "Sticker on Amp Gives Seller Away"],
