        summary: "{V} came home from a week on the road on {DATE} to find an amp and pedalboard gone from the band's practice room. An online listing showed the same amp with {V}'s band sticker. The seller account used {D}'s phone number. The serial number matched. {DL} says {V} told {D.him} to sell the gear.",
        state: [E(.digital, 3, "Online Listing", "Photos of the amp with {V}'s band sticker, with {D}'s phone number as contact."), E(.document, 3, "Serial Number", "Matches {V}'s purchase receipt.")],
        defense: [E(.statement, 1, "Told to Sell", "{DL} says {V} said to sell the gear.")],
        role: "Bandmate",
        exam: [.direct("What can you tell us about your band?", "\"We are a band that plays gigs on weekends and goes on the road. We keep an amp and a pedalboard in a practice room, and I paid for the amp.\""), .direct("What happened when you came home on {DATE}?", "\"I came home from a week on the road and found the amp and pedalboard gone from the practice room.\""), .direct("How did you find the amp?", "\"An online listing showed the same amp with my band sticker. The seller account used {D}'s phone number.\""), .direct("What matched?", "\"The serial number matches my purchase receipt. It was my amp.\""), .direct("What did {D} say?", "\"{D} said I told {D} to sell the gear. I never said that.\""), .direct("How did this affect you?", "\"I lost gear I needed for gigs. I was angry and hurt that a bandmate took it.\""), .cross("Did you tell {D} to sell the gear?", "\"No. I did not. I may have mentioned selling before I left, but I never said to sell it.\""), .cross("Did you call {D} the day before leaving?", "\"Yes. I did. I mentioned selling in passing. I did not mean the amp.\""), .cross("Did you mention selling to {D} at all?", "\"Possibly. A call log shows we spoke. I do not recall the exact words.\""), .cross("Was the amp insured?", "\"No. It was not. I paid for it myself.\""), .cross("Did {D} offer to return it?", "\"No. {D} did not offer. I had to find it online.\"")],
        theory: ("{D} listed a bandmate's gear for sale.", "Permission to sell."),
        allocution: "\"I needed money. I'm sorry.\"",
        truths: ("{DL} messaged a friend, '{V.he}'s out of town, it'll sell fast.'", "A call log shows {V} calling {DL} the day before leaving and mentioning selling."),
        defendant: [.direct("Tell us about your relationship with {V}.", "\"We are bandmates. We have played together for years. I thought we were close.\""), .direct("Why did you sell the amp?", "\"{V} told me to sell the gear. A call log shows {V} calling me the day before leaving and mentioning selling.\""), .direct("Why did you message a friend that it would sell fast?", "\"I wrote that {V} was out of town and it would sell fast. I meant I would sell it while {V} was away, and I know that looks bad.\""), .direct("Did {V} agree in writing?", "\"No. It was a phone call. I did not get anything in writing.\""), .direct("Why did you use your own phone number?", "\"I had nothing to hide. I thought {V} had agreed, and I did not think I needed to use another number.\""), .direct("How are you coping with what happened?", "\"Mostly I feel stupid. I may have misunderstood. I wish I had asked {V} again.\""), .cross("You listed {V}'s amp with your own phone number, didn't you?", "\"Yes. I did. I thought it was fine.\""), .cross("The serial number matches {V}'s receipt, doesn't it?", "\"Yes. It is {V}'s amp. I did not say it was mine.\""), .cross("You wrote that it would sell fast because {V} was out of town, didn't you?", "\"Yes. I did. I see how it looks.\""), .cross("You never asked {V} again before selling, did you?", "\"No. I did not. I assumed it was settled.\""), .cross("You never got anything in writing from {V}, did you?", "\"No. We talked by phone. I should have sent a message or waited until {V} was back before I listed the gear.\"")],
        openings: ("{V} came home from a week on the road on {DATE} to find an amp and pedalboard gone from the band's practice room. An online listing showed the same amp with {V}'s band sticker, the seller account used {D}'s phone number, and the serial number matched.", "The defense will present a call log that shows {V} calling {D} the day before leaving and mentioning selling, and a person who believed {V} had agreed. A misunderstanding between bandmates is not a theft."),
        closings: ("An amp with {V}'s band sticker, a listing with {D}'s phone number, a matching serial number, and a message that said it would sell fast because {V} was out of town.", "A call the day before {V} left that mentioned selling, and a bandmate who believed {V} agreed. The State cannot show that {D} acted without {V}'s blessing."),
        timeline: [(-7, "{V} leaves for a week."), (-2, "{DL} lists the gear online."), (0, "{V} returns and finds the room empty.")],
        identified: "An online listing and a serial number.",
        mood: .wantsConviction,
        impact: "I built that pedalboard over ten years.",
        genders: ["V": .male])

    static let fakeBadgeTrickV1 = SmallCases.make(
        key: "story.fakeBadgeTrick",
        category: .publicOrder,
        headlines: ["Festival Lot Attendant Waves in Driver Who Flashed Badge Wallet", "Novelty Special Agent ID Found in Glove Box"],
        law: "impersonatingLEO",
        spec: "Falsely pretended to be a law enforcement officer, displaying a badge, to obtain a benefit, on {DATE}.",
        ages: 22...60,
        victim: false,
        summary: "At a county festival on {DATE}, a parking attendant waved {D} through the $15 lot after {D} held up a badge wallet and said, \"County, on duty.\" The wallet was a novelty 'Special Agent' ID. The attendant noticed it was plastic and reported it. {DL} says it was a joke and the attendant was just waving in staff.",
        state: [E(.video, 3, "Attendant's Phone Video", "{D} holds up the wallet and says, 'County, on duty.'"), E(.physical, 2, "Novelty Wallet", "A plastic 'Special Agent' ID found in the glove box.", .search)],
        defense: [E(.statement, 1, "A Joke", "{DL} says it was a joke.")],
        role: "Parking attendant",
        exam: [.direct("Describe your job as a parking attendant for the jury.", "\"I work the lot at county festivals. I collect the $15 fee, wave staff and emergency vehicles through, and keep the lines moving.\""), .direct("What happened on {DATE}?", "\"{D} held up a badge wallet and said, County, on duty. I waved {D} through the lot without paying.\""), .direct("What did you notice about the wallet?", "\"It was a novelty Special Agent ID. When I looked closely, it was plastic.\""), .direct("What did you do?", "\"I reported it. I filmed {D} on my phone as {D} said the words.\""), .direct("How did this affect your work?", "\"I let {D} through, and I should not have. I was concerned about others doing the same.\""), .direct("Did {D} say anything more?", "\"Only the words and a smile. {D} did not argue after.\""), .cross("Did you wave others in that day?", "\"Yes. I was told to let in anyone with a lanyard, and I waved in a dozen others.\""), .cross("Was {D} wearing a lanyard?", "\"I do not remember. {D} held the wallet. I did not check anything else.\""), .cross("Did {D} say it was a joke?", "\"Yes. {D} said it was a joke. I did not hear it at the time.\""), .cross("Had {D} used the wallet before?", "\"I understand {D} used it at two other events that month. I did not know that then.\""), .cross("Did {D} claim to be an officer?", "\"{D} said County, on duty. That is not exactly claiming to be an officer, but it was close.\"")],
        theory: ("{D} flashed a fake badge to skip the lot fee.", "A joke with a plastic wallet."),
        allocution: "\"It was a dumb joke. I'll pay the lot fee.\"",
        truths: ("{DL} had used the wallet at two other events that month.", "The attendant had been told to let in anyone with a lanyard and waved in a dozen others that day."),
        defendant: [.direct("What can you tell us about the festival?", "\"I went to a county festival. I held up a novelty badge wallet and said County, on duty, as a joke.\""), .direct("Why did you do it?", "\"It was a joke. I thought the attendant would laugh. I did not expect to be waved through.\""), .direct("Was the wallet real?", "\"No. It is a novelty Special Agent ID. It is plastic, and I bought it as a gag.\""), .direct("Had you used it before?", "\"Yes. At two other events that month. It was a joke each time, and nobody minded.\""), .direct("Did you mean to avoid the $15 fee?", "\"Not really. It was a joke. I know it looks like I was trying to skip the fee.\""), .direct("How do you feel about it?", "\"I would say I feel embarrassed. It was a silly joke, and it turned into a case.\""), .cross("You held up a badge wallet and said County, on duty, didn't you?", "\"Yes. I did. I know how it sounds.\""), .cross("The attendant waved you through without paying, didn't the attendant?", "\"Yes. I did not pay the $15. I know In hindsight, yes.\""), .cross("You used the wallet at two other events, didn't you?", "\"Yes. I did. It was a joke each time.\""), .cross("The wallet says Special Agent, doesn't it?", "\"Yes. It is a novelty item. I know it can look real.\""), .cross("You are not a county employee, are you?", "\"No. I am not. I know the joke was misleading.\"")],
        openings: ("At a county festival on {DATE}, a parking attendant waved {D} through the $15 lot after {D} held up a badge wallet and said, County, on duty. The wallet was a novelty Special Agent ID, and the attendant noticed it was plastic and reported it.", "The defense will present a novelty item bought as a joke, an attendant who had been told to let in anyone with a lanyard, and a dozen others waved in that day. A joke at a gate is not a crime of intent."),
        closings: ("A plastic badge wallet, the words County, on duty, a video from the attendant, and a $15 fee skipped. {D} had used the wallet at two other events that month.", "A joke with a novelty wallet at a gate where a dozen others were waved in. The State has not proved that {D} meant to impersonate an officer."),
        timeline: [(0, "10 a.m.: {DL} reaches the festival lot."), (0, "10:02 a.m.: the wallet is shown."), (1, "The attendant sends the video to deputies.")],
        identified: "The attendant's phone video.",
        genders: ["D": .male, "V": .male])

    static let witnessThreatV1 = SmallCases.make(
