        role: "Parks department groundskeeper",
        exam: [.direct("What does your work as a parks groundskeeper involve?", "\"I care for the town's ballfields. I mow, paint lines, repair fences, and make sure the fields are ready for games.\""), .direct("What did you find on {DATE}?", "\"A dugout, scoreboard wiring, and a fence at the town ballfield were spray-painted and cut overnight.\""), .direct("What did the field camera show?", "\"A hooded figure in bright orange sneakers spraying the dugout.\""), .direct("What matched the paint?", "\"Paint on {D}'s shoes matched the paint at the field.\""), .direct("What was in the group chat?", "\"A photo showed {D} holding a spray can that night.\""), .direct("How much was the damage?", "\"The repairs cost the town thousands of dollars, and we had to delay games.\""), .cross("Did you see anyone spray the dugout?", "\"No. I found it in the morning. I only know what the camera shows.\""), .cross("Can you see the face on the field camera?", "\"No. The hood hides it. I see orange sneakers and a figure.\""), .cross("Are orange sneakers common?", "\"Many teenagers wear them. I cannot say how many in town.\""), .cross("Did another teen confess?", "\"Yes. Another teen later confessed and was found with matching cans.\""), .cross("Did {D} deny it?", "\"Yes. {D} says the paint came from a friend's fence.\"")],
        theory: ("{D} sprayed and cut the ballfield.", "Paint from a friend's fence."),
