        spec: "Willfully made a false report to law enforcement that a person was armed and fighting at a house, on {DATE}.",
        ages: 19...50,
        victim: false,
        summary: "A text to 911 on {DATE} reported a man with a gun fighting in a driveway on a quiet street. Four deputies arrived to find a neighbor washing his car. The text came from a free messaging app account registered with an email tied to {D}, who lives next door and has argued with the neighbor over a fence. {DL} says {D.he} was at work and the email was used by others.",
        state: [E(.digital, 3, "Text-to-911 Log", "A text from a messaging app reports a man with a gun at the neighbor's address."), E(.document, 2, "App Account Records", "The account email is {D}'s and was created two days earlier.")],
        defense: [E(.statement, 1, "At Work", "{DL}'s time clock shows {D.him} at work during the text.")],
        role: "Sheriff's detective",
        exam: [.direct("Walk the jury through your work as a sheriff's detective.", "\"I investigate false reports and threats. I trace accounts, review logs, and work with the 911 center to find who sends false alarms.\""), .direct("What did the text to 911 say on {DATE}?", "\"It reported a person with a gun fighting in a driveway on a quiet street. The text came from a messaging app.\""), .direct("What did deputies find?", "\"Four deputies arrived to find a neighbor washing a car. There was no gun and no fight.\""), .direct("How did you trace the text?", "\"The messaging app account was registered with an email tied to {D}, who lives next door. The account was created two days earlier.\""), .direct("What do you know about {D} and the neighbor?", "\"{D} has argued with the neighbor over a fence. Doorbell clips show {D} arguing with the neighbor an hour before.\""), .direct("What did {D} say?", "\"{D} said {D} was at work and that the email was used by others.\""), .cross("Where was {D} at the time of the text?", "\"A time clock shows {D} at work during the text. I cannot place {D} at the home.\""), .cross("Who else used {D}'s email?", "\"{D}'s roommate admitted using {D}'s email to set up the app.\""), .cross("Did you identify who sent the text?", "\"No. We know the account. We do not know who typed the message.\""), .cross("Was anyone hurt?", "\"No. But four deputies responded, and a neighbor was frightened.\""), .cross("Did {D} cooperate?", "\"Yes. {D} gave the roommate's name and showed the time clock.\"")],
        theory: ("{D} used a new account to send deputies against a neighbor.", "A worker at a time clock whose email was borrowed."),
        allocution: "\"I was angry about the fence. I'm sorry for the trouble.\"",
        truths: ("Doorbell clips show {DL} arguing with the neighbor an hour before.", "{DL}'s roommate admitted using {DL}'s email to set up the app."),
        defendant: [.direct("What can you tell us about your neighbor?", "\"We have argued over a fence line. It was heated, but I never wanted to hurt anyone.\""), .direct("Did you send the text to 911?", "\"No. I did not. I was at work. My time clock shows it.\""), .direct("Whose email was used to create the account?", "\"Mine. My roommate used my email to set up the app. I did not know until deputies came.\""), .direct("Why did you argue with the neighbor an hour before?", "\"It was about the fence. We were both upset. I went to work after.\""), .direct("What did your roommate say?", "\"My roommate admitted using my email. I was angry. I did not tell my roommate to do it.\""), .direct("Looking back, how do you feel about it?", "\"I feel betrayed by my roommate and scared of being blamed. I did not send the text.\""), .cross("The account email is yours, isn't it?", "\"Yes. It is. My roommate used it without my permission.\""), .cross("You argued with the neighbor an hour before, didn't you?", "\"Yes. I did. I was angry, but I did not report a false gun.\""), .cross("The account was created two days earlier, wasn't it?", "\"Yes. I did not create it. I only learned about it later.\""), .cross("You live next door, don't you?", "\"Yes. I do. That is why the dispute was heated.\""), .cross("Your roommate lives with you, doesn't your roommate?", "\"Yes. Which is why my email was easy to use.\"")],
