        mood: .indifferent,
        genders: ["D": .male])

    static let tireIronV1 = SmallCases.make(
        key: "story.tireIron",
        category: .violent,
        headlines: ["Fender-Bender in Grocery Lot Ends With Bat Swung at Windshield", "Cart Attendant's Account Splits Two Drivers"],
        law: "awdw",
        threshold: 3,
        spec: "Assaulted {V} with a deadly weapon, a baseball bat, by swinging it at {V.him}.",
        ages: 35...60,
        victim: true,
        summary: "After a fender-bender in a grocery lot on {DATE}, {V} and {D} argued by their cars. {D} took a baseball bat from the trunk and swung it at {V}'s windshield with {V} behind the wheel. The glass cracked. Witnesses disagree on what {V} did first: one says {V} lunged and shouted threats, another says {V} stayed seated and yelled. {DL} says {V} threatened to run {D.him} over. This case was tried in district court and appealed.",
        state: [E(.video, 2, "Store Camera", "{D} takes a bat from the trunk and swings at a windshield."), E(.physical, 2, "Bat", "A wooden bat recovered from {D}'s trunk."), E(.statement, 2, "Cart Attendant", "The attendant told police {D} 'came out swinging' while {V} stayed in the car.")],
        defense: [E(.digital, 2, "Dash Camera Audio", "Audio from {D}'s dash camera captures {V} yelling, 'I'll run you over.'"), E(.statement, 2, "Passenger", "A passenger in {D}'s car says {V} revved the engine toward {D.him}."), E(.physical, 1, "Tire Marks", "Fresh tire marks near {D}'s front bumper.")],
        role: "Other driver",
        exam: [.direct("Describe the fender-bender for the jury.", "\"I was driving in a grocery lot when {D} and I had a fender-bender. We got out and argued by our cars.\""), .direct("What did {D} do?", "\"{D} took a baseball bat from the trunk and swung it at my windshield while I was behind the wheel.\""), .direct("What happened to the glass?", "\"It cracked. Pieces fell inside, and I was afraid. I stayed in the car and shouted.\""), .direct("What did you do before the swing?", "\"I stayed seated and yelled. I did not lunge, and I did not threaten to run {D} over.\""), .direct("What did the grocery camera in another lot show?", "\"Me backing away before {D} swung. That supports what I said.\""), .direct("What did a cart attendant tell police?", "\"That {D} came out swinging while I stayed in the car.\""), .cross("Did you shout, I'll run you over?", "\"The dash camera audio, enhanced later, records me shouting that. I was angry and afraid.\""), .cross("Did you rev your engine?", "\"A passenger in {D}'s car says I revved the engine toward {D}. I may have, in a panic.\""), .cross("Were there tire marks near {D}'s bumper?", "\"Fresh tire marks. They may be from my car moving when I backed away.\""), .cross("Did you lunge at {D}?", "\"One witness says I lunged. I did not. I stayed in the car.\""), .cross("Why did the other witness disagree?", "\"People saw different moments. I cannot explain their memories.\"")],
        defenseRole: "Passenger in {D}'s car",
        defenseExam: [.direct("Tell the jury how you know {D}.", "\"I was a passenger in {D}'s car. We were going to the store together, and I saw everything.\""), .direct("What did you see {V} do?", "\"{V} shouted and revved the engine toward {D}. I thought {V} might hit {D}.\""), .direct("What did {D} say?", "\"{D} was frightened. {D} said {V} threatened to run {D} over, and {D} grabbed the bat.\""), .direct("What did you hear on the audio?", "\"{V} yelling, I'll run you over. I heard it too.\""), .direct("How did {D} act after?", "\"Shaken and sorry. {D} said it went too far and apologized to {V}.\""), .direct("What kind of person is {D}?", "\"Calm and polite. I never saw {D} lose control before that day.\""), .cross("Did you see {V} lunge?", "\"No. I did not. I saw {V} in the car, shouting and revving.\""), .cross("Did you see {D} swing the bat?", "\"Yes. I saw {D} swing at the windshield. I was shocked.\""), .cross("Was {V} backing away?", "\"I saw {V}'s car move. I do not know whether {V} was backing away or coming forward.\""), .cross("Did you try to stop {D}?", "\"I shouted for {D} to stop. I did not get out in time.\""), .cross("Did {D} get the bat from the trunk?", "\"Yes. {D} went to the trunk and took it. I did not expect that.\"")],
        theory: ("{D} grabbed a bat and swung it at a driver after a minor collision.", "{V} threatened to run {D} over and {D} struck the glass to stop it."),
        allocution: "\"I shouldn't have picked up that bat. I was afraid.\"",
        truths: ("A grocery camera in another lot shows {V} backing away before {D} swung.", "The dash camera audio, enhanced later, clearly records {V} shouting, 'I'll run you over.'"),
